_validHitAuthorityMetadata(d) {
  const present = HIT_AUTHORITY_FIELDS.filter((key) => d?.[key] !== undefined).length;
  if (present === 0) return d?.he === undefined;
  if (present !== 4 || !hitSafe(d.h) || d.h < 1
    || !hitSafe(d.v) || d.v < 0 || !hitSafe(d.a) || d.a < 0
    || !hitSafe(d.vl) || d.vl < 0 || !hitFinite(d.d) || d.d < 0
    || (d.kld !== 0 && d.kld !== 1) || !hitFinite(d.hp)
    || d.hp < 0 || d.hp > PLAYER.hp || !hitSafe(d.hr) || d.hr < 1
    || !hitFinite(d.ht) || d.ht < 0
    || (d.la !== 0 && d.la !== 1) || (d.kld === 1 && (d.hp !== 0 || d.la !== 0))
    || (d.kld === 0 && d.la !== 1)) return false;
  return d.he == null || this._readHitHandoffPacket(d.he) !== false;
}

record:
function record(nm,from,packet,t,acceptedSub=null) {
  if(!Array.isArray(packet?.e) || packet.e.length>512 || !finite(packet.ts) || packet.ts<0 || packet.ts>1e9)return;
  const s=state(nm);prune(s,t);
  const poses=nm._combatPoseScratch||(nm._combatPoseScratch=new Map());poses.clear();
  if(Array.isArray(packet.a))for(const r of packet.a) {
    if(!Array.isArray(r)||r.length<4 || !v3(r.slice(1,4)))continue;
    if(ownerActor(nm,from,r[0]))poses.set(r[0],r.slice(1,4));
  }
  const store=s.proofs.get(from)||[];let acceptedProof=null;
  const packetStart=store.length;
  // A burst shares one exact index; ordinary small envelopes retain the
  // allocation-free walk. Only accepted proofs extend either index.
  let proofKeys=null,recentByActor=null;
  for(let i=0;i<Math.min(packet.e.length,256);i++) {
    const candidate=proofFromEvent(nm,from,packet.e[i],poses,packet.ts,t,acceptedSub);
    if(!candidate)continue;
    if(!proofKeys&&packet.e.length>=32){
      proofKeys=new Set();recentByActor=new Map();
      for(const proof of store){proofKeys.add(proof.key);if(t-proof.at<1)recentByActor.set(proof.actor,(recentByActor.get(proof.actor)||0)+1);}
    }
    let duplicate=false,recent=0;
    if(proofKeys){duplicate=proofKeys.has(candidate.key);recent=recentByActor.get(candidate.actor)||0;}
    else for(const proof of store) {
      if(proof.key===candidate.key){duplicate=true;break;}
      if(proof.actor===candidate.actor && t-proof.at<1)recent++;
    }
    if(duplicate)continue;
    // #1665: one main shot records its projectile birth ('p') and then its
    // weapon:fire presentation event in the same frame. Both used to mint a
    // proof, doubling the hits one real round could authorize. The fire event
    // still proves hitscan shots (Charger), which have no projectile birth.
    if(candidate.src==='ev'&&candidate.kind==='main'&&sameShotBirth(store,packetStart,candidate))continue;
    const actor=ownerActor(nm,from,candidate.actor);
    const interval=actor?.weapon?.fireInterval;
    const rate=finite(interval)&&interval>0 ? Math.min(75,Math.ceil(2/interval)+6):32;
    if(recent>=rate)continue;
    store.push(candidate);if(acceptedSub)acceptedProof=candidate;
    if(proofKeys){proofKeys.add(candidate.key);if(t-candidate.at<1)recentByActor.set(candidate.actor,recent+1);}
  }
  if(store.length)s.proofs.set(from,store.slice(-MAX_PROOFS));return acceptedProof;
}

boss:
export function validBossSnapshotRow(row, timestamp) {
  if (!Array.isArray(row) || (row.length !== 18 && row.length !== 19) || !validSnapshotTimestamp(timestamp)) return false;
  if (!validSnapshotTimestamp(row[0])) return false;
  for (const i of SNAPSHOT_FIELDS_0) if (!bounded(row[i], -1e6, 1e6)) return false;
  for (const i of [5, 6]) if (!bounded(row[i], -1e4, 1e4)) return false;
  if (!bounded(row[4], -1e5, 1e5) || !bounded(row[12], -1e5, 1e5)) return false;
  if (!finite(row[7]) || !finite(row[17]) || row[17] <= 0) return false;
  if (!integer(row[8], 1, 3) || !integer(row[9], 0, 15) || !integer(row[11], 0, 2)) return false;
  if (row[10] !== -1 && !validSnapshotTimestamp(row[10])) return false;
  for (const i of [13, 14]) if (!integer(row[i], 0, Number.MAX_SAFE_INTEGER)) return false;
  if (!integer(row[15], -1, Number.MAX_SAFE_INTEGER) || !Array.isArray(row[16]) || row[16].length > NETWORK_BOSS_CRABLET_LIMIT) return false;
  const crabIds = new Set();
  for (const crab of row[16]) {
    if (!Array.isArray(crab) || crab.length !== 6 || !integer(crab[0], 0, Number.MAX_SAFE_INTEGER) || crabIds.has(crab[0])) return false;
    crabIds.add(crab[0]);
    for (const i of SNAPSHOT_FIELDS_0) if (!bounded(crab[i], -1e6, 1e6)) return false;
    if (!bounded(crab[4], -1e5, 1e5) || !finite(crab[5])) return false;
  }
  return row[18] == null || validBossMove(row[18]);
}

diorama:
let best = -1, bd = 72;
for (let i = 0; !padChoice && i < selfIndex; i++) {
  const p = this.pins[i];
  if (!p.vis) continue;
  const d = Math.hypot(p.x - this.cx * W, p.y - 34 - this.cy * H);
  if (d < bd) { bd = d; best = i; }
}

objectiveText:
export function objectiveText(engine, G, api = {}) {
  const t = (text, vars) => rankedText(api.LANG, text, vars);
  const state = engine.rule?.state || {}, frame = engine.frame || {};
  if (engine.mode === 'zones') {
    const coverage = frame.zoneCoverage || [];
    const captured = state.zones || [];
    if (coverage.length) return coverage.map((pair, i) => {
      const a = Math.round(clamp01(pair?.[0]) * 100), b = Math.round(clamp01(pair?.[1]) * 100);
      const owner = captured[i]?.team;
      return `${t('ZONE {n}', { n: i + 1 })} ${a}/${b}${owner === 0 || owner === 1 ? ` · ${t(teamName(owner, G.palette?.names || G.match?.palette?.names))}` : ''}`;
    }).join('   ');
    return state.controllingTeam === 0 || state.controllingTeam === 1
      ? t('{team} CONTROLS ALL ZONES', { team: t(teamName(state.controllingTeam, G.palette?.names || G.match?.palette?.names)) }) : t('CAPTURE ALL ZONES');
  }
  if (engine.mode === 'tower') {
    const p = Math.round(clamp01(state.progress) * 100);
    const team = state.controllingTeam;
    const index = (state.checkpointIndex?.[team] || 0) + 1;
    const total = engine.stage?.tower?.checkpoints?.[team]?.length || 0;
    return t('{team} TOWER · {progress}%', { team: t(teamName(team, G.palette?.names || G.match?.palette?.names)), progress: p }) + (total ? ' · ' + t('CP {index}/{total}', { index: Math.min(index, total), total }) : '');
  }
  if (engine.mode === 'rainmaker') {
    if (state.goalHold) return t('DUNKING · PROTECT THE CARRIER!');
    if (state.respawnRemaining > 0) return t('REFORMING SHIELD · {n}s', { n: Math.ceil(state.respawnRemaining) });
    const barrier = state.barrier;
    if (barrier?.active) {
      const max = Math.max(0, finite(barrier.max));
      const pressure = Math.min(max, Math.abs(finite(barrier.balance)));
      return t('SHIELD {pressure} / {max}', { pressure: Math.ceil(pressure), max: Math.ceil(max) });
    }
    if (state.carrier != null) {
      const actor = (G.match?.actors || []).find(a => String(a.nid ?? `${a.team}:${a.slot}`) === String(state.carrier));
      const held = Math.ceil(Math.max(0, finite(state.holderRemaining)));
      const charge = Math.round(clamp01(state.charge?.value) * 100);
      return t('CARRY {held}s · {name} · CHARGE {charge}%', { held, name: actor?.name || t(teamName(actor?.team)), charge }) + (state.retreatRate > 1 ? ' · ' + t('RETREAT!') : '');
    }
    const owner = state.lastCarrierTeam;
    return owner === 0 || owner === 1 ? t('RAINMAKER DROPPED · PICK IT UP') : t('SHIELD POPPED · PICK UP THE RAINMAKER');
  }
  if (engine.mode === 'clams') {
    const local = G.match?.local;
    const team = local?.team === 0 || local?.team === 1 ? local.team : -1;
    const inventory = state.inventories || {};
    const localId = local ? String(local.nid ?? `${local.team}:${local.slot}`) : '';
    const own = inventory[localId];
    let carried = 0;
    if (!own && team >= 0) for (const id in inventory) if (Object.hasOwn(inventory, id)) {
      const item = inventory[id];
      if (item?.team === team) carried = carried + finite(item?.small) + finite(item?.power ? 8 : 0);
    }
    const basket = team >= 0 ? state.baskets?.[team] : null;
    const count = own ? (own.power ? t('POWER CLAM') : t('{n}/8 CLAMS', { n: Math.ceil(finite(own.small)) }))
      : team >= 0 ? t('{n} CLAMS ON TEAM', { n: Math.ceil(carried) }) : t('COLLECT CLAMS');
    const scored = team >= 0 ? Math.ceil(finite(state.scoredPoints?.[team])) : 0;
    const basketLabel = basket?.barrierOpen
      ? t('BASKET OPEN · {n}s', { n: Math.ceil(Math.max(0, finite(basket.openTimer))) })
      : basket ? t('BASKET CLOSED') + (finite(basket.cooldown) > 0 ? ' · ' + t('{n}s', { n: Math.ceil(basket.cooldown) }) : '') : '';
    return `${count} · ${t('{n} SCORED', { n: scored })}${basketLabel ? ` · ${basketLabel}` : ''}`;
  }
  return '';
}
